export const BODY: string = "\n<p>SVG لوگو لامحدود اسکیل ہوتا ہے، مگر کئی جگہیں اب بھی PNG مانگتی ہیں۔ اسے بدلنے میں سیکنڈ لگتے ہیں، اور صرف فیصلہ جو اہم ہے، وہ آؤٹ پٹ سائز ہے۔</p>\n<p>درست اسکیل چنیں تو PNG بہترین لگتا ہے۔ غلط چنیں تو وہ دھندلا یا غیر ضروری بڑا نکلتا ہے۔</p>\n<p>یہ رہنما ہر مرحلہ بتاتا ہے، SVG اپ لوڈ کرنے سے لے کر تیز PNG ڈاؤن لوڈ کرنے تک۔</p>\n<h2 id=\"before-you-start\">شروع کرنے سے پہلے: SVG تیار کریں</h2>\n<p>پہلے SVG کو براؤزر میں کھولیں اور یقین کریں کہ وہ درست رینڈر ہوتا ہے۔ اگر وہاں غلط لگے تو PNG کے طور پر بھی غلط لگے گا۔</p>\n<p>اگر SVG میں حرف ہیں تو اپنے ڈیزائن ٹول میں متن کو آؤٹ لائن میں بدلیں۔ آؤٹ لائن شدہ متن شکلیں بن جاتا ہے، اس لیے وہ فونٹ سے قطع نظر بالکل رینڈر ہوتا ہے۔</p>\n<p>لنک شدہ تصویریں SVG کے اندر data URI کے طور پر ایمبیڈ کریں۔ کنورٹر بیرونی فائلیں نہیں لا سکتا، اس لیے لنک شدہ تصویر PNG سے گم ہو جائے گی۔</p>\n<h2 id=\"step-1-open-tool\">مرحلہ 1: SVG سے PNG ٹول کھولیں</h2>\n<p>براؤزر میں <a href=\"/ur/svg-ko-png-mein-convert-karein/\">SVG to PNG ٹول</a> کھولیں۔ یہ صفحہ ونڈوز، میک، لینکس، کروم او ایس، اینڈرائیڈ اور آئی او ایس پر کام کرتا ہے۔</p>\n<p>آپ کو اپ لوڈ والا حصہ اور اسکیل چننے والا دکھائی دے گا۔ یہ دو کنٹرول ہی پورا کام ہیں۔</p>\n<p>اکاؤنٹ کی ضرورت نہیں ہے، اور کچھ بھی اپ لوڈ نہیں ہوتا۔ تبدیلی آپ کے آلے پر ہوتی ہے، جو کلائنٹ لوگو اور برانڈ اثاثوں کے لیے اہم ہے۔</p>\n<h2 id=\"step-2-upload\">مرحلہ 2: اپنی SVG فائلیں اپ لوڈ کریں</h2>\n<p>اپنی SVG فائلیں اپ لوڈ والے حصے پر گھسیٹ دیں، یا فائل پکر کھولنے کے لیے اس پر کلک کریں۔ بیچ کے لیے کئی فائلیں ایک ساتھ چن سکتے ہیں۔</p>\n<p>ہر فائل تھمب نیل والے کارڈ کے طور پر دکھائی دیتی ہے، تاکہ آپ یقین کر سکیں کہ درست فائلیں لوڈ ہوئیں۔ غلط فائل آسانی سے نظر آتی ہے اور ہٹائی جا سکتی ہے۔</p>\n<p>ہر فائل 25 MB تک قبول ہوتی ہے، جو ہزاروں راستوں والی بڑی تصویری فائلوں کو بھی پوری کرتی ہے۔ بہت پیچیدہ SVG بس ایک یا دو سیکنڈ زیادہ لیتے ہیں۔</p>\n<h2 id=\"step-3-scale\">مرحلہ 3: آؤٹ پٹ اسکیل چنیں</h2>\n<p>اسکیل چننے والا 1x، 2x، 3x اور 4x دیتا ہے۔ اسکیل SVG کے قدرتی سائز کو ضرب دیتا ہے، اس لیے 24 پکسل آئیکن 4x پر 96 پکسل PNG بن جاتا ہے۔</p>\n<p>ویب سائٹ آئیکن کے لیے 2x یا 3x عام طور پر کافی ہے۔ PNG ریٹنا اسکرین پر تیز لگتا ہے، بغیر بائٹ ضائع کیے۔</p>\n<p>پریزنٹیشن سلائیڈ پر لوگو کے لیے 4x آرام دہ مارجن دیتا ہے۔ پاورپوائنٹ میں بڑا کیا گیا چھوٹا لوگو تیز رہتا ہے جب PNG میں کافی پکسل ہوں۔</p>\n<h2 id=\"step-4-convert\">مرحلہ 4: فائلیں بدلیں</h2>\n<p>Convert بٹن پر کلک کریں۔ ٹول ہر SVG کو چنے ہوئے اسکیل پر کینوس پر بناتا ہے اور نتیجہ PNG کے طور پر انکوڈ کرتا ہے۔</p>\n<p>تبدیلی تیز ہوتی ہے، عام طور پر فی فائل ایک یا دو سیکنڈ۔ ہزاروں راستوں والی بہت پیچیدہ SVG بنانے میں تھوڑا زیادہ وقت لیتی ہیں۔</p>\n<p>ہر کارڈ نیا PNG سائز اور ابعاد دکھا کر اپ ڈیٹ ہوتا ہے۔ ابعاد جانچ کر یقین کریں کہ اسکیل نے وہ سائز بنایا جس کی آپ کو توقع تھی۔</p>\n<h2 id=\"step-5-check\">مرحلہ 5: نتیجہ جانچیں</h2>\n<p>کسی کارڈ پر Compare پر کلک کر کے SVG اور PNG ساتھ ساتھ دیکھیں۔ لوگو کناروں میں زوم کریں اور یقین کریں کہ وہ تیز اور صاف ہیں۔</p>\n<p>اگر SVG میں کوئی متن ہو تو اسے پہلے جانچیں۔ غلط لگنے والا متن گم شدہ فونٹ بتاتا ہے، اور حل متن کو آؤٹ لائن میں بدل کر دوبارہ بدلنا ہے۔</p>\n<p>گم شدہ تصویریں جانچیں۔ خالی جگہ جہاں تصویر ہونی چاہیے، بتاتی ہے کہ تصویر بیرونی طور پر لنک تھی، اور آپ کو اسے data URI کے طور پر ایمبیڈ کرنا ہے۔</p>\n<h2 id=\"step-6-download\">مرحلہ 6: PNG فائلیں ڈاؤن لوڈ کریں</h2>\n<p>ایک PNG محفوظ کرنے کے لیے کسی کارڈ پر Download پر کلک کریں۔ فائل نام آپ کا اصل نام .png ایکسٹینشن کے ساتھ رکھتا ہے۔</p>\n<p>بیچ کے لیے Download All پر کلک کر کے ایک ZIP لیں جس میں ہر بدلی ہوئی PNG ہو۔ یہ ایک ایک کر کے ڈاؤن لوڈ کرنے سے کہیں تیز ہے۔</p>\n<p>استعمال سے پہلے ڈاؤن لوڈ شدہ فائلیں ایک بار جانچیں۔ PNG اپنے فوٹو ویور میں کھولیں اور یقین کریں کہ وہ آپ کے مطلوبہ سائز پر تیز لگتی ہے۔</p>\n<ol>\n<li>SVG سے PNG ٹول کھولیں اور اپنی SVG فائلیں اپ لوڈ کریں۔</li>\n<li>اسکیل چنیں: ویب کے لیے 2x، پریزنٹیشن اور پرنٹ کے لیے 4x۔</li>\n<li>بدلیں اور کنارے، متن اور شفافیت جانچیں۔</li>\n<li>اکیلی PNG ڈاؤن لوڈ کریں یا پورا بیچ ZIP کے طور پر ڈاؤن لوڈ کریں۔</li>\n</ol>\n<h2 id=\"converting-an-icon-pack\">پورا آئیکن پیک بدلنا</h2>\n<p>فائل پکر میں تمام SVG آئیکن ایک ساتھ چنیں۔ وہ قطار میں لوڈ ہو جاتے ہیں، اور ایک کلک سے سب اسی اسکیل پر بدل جاتے ہیں۔</p>\n<p>پورے پیک کے لیے ایک ہی اسکیل استعمال کریں۔ مستقل مزاجی اہم ہے جب آئیکن ساتھ دکھائی دیں، کیونکہ ملے جلے سائز غیر ہموار لگتے ہیں۔</p>\n<p>بدلنے کے بعد دو یا تین آئیکن جانچیں، پچاس سب نہیں۔ اگر وہ اچھے لگیں تو باقی بھی اچھے ہوں گے، کیونکہ ترتیبات ایک جیسی ہیں۔</p>\n<h2 id=\"choosing-size-for-purpose\">ہر مقصد کے لیے سائز چننا</h2>\n<p>فیویکن کے لیے سائٹ کو مطلوبہ بالکل سائز پر ریسٹرائز کریں، عام طور پر 16، 32 اور 48 پکسل۔ فیویکن جنریٹر PNG سے وہ سائز بھی بنا سکتا ہے۔</p>\n<p>سوشل میڈیا اوتار کے لیے 400 بہ 400 پکسل اچھا سائز ہے۔ یہ ڈیسک ٹاپ اور موبائل پر تیز لگتا ہے، اور فائل چھوٹی رہتی ہے۔</p>\n<p>پریزنٹیشن لوگو کے لیے SVG سائز کا 4x عام طور پر کافی پکسل دیتا ہے۔ 4x پر 100 پکسل لوگو 400 پکسل بن جاتا ہے، جو سلائیڈ پر تیز لگتا ہے۔</p>\n<h2 id=\"fixing-problems\">عام مسائل کا حل</h2>\n<p>اگر PNG دھندلا لگے تو اسکیل بہت کم تھا۔ SVG اصل سے اونچے اسکیل پر دوبارہ ریسٹرائز کریں، کیونکہ کم ریزولوشن PNG تیز نہیں ہو سکتا۔</p>\n<p>اگر متن غلط لگے تو فونٹ گم ہے۔ اپنے ڈیزائن ٹول میں متن کو آؤٹ لائن میں بدلیں اور دوبارہ بدلیں۔</p>\n<p>اگر لنک شدہ تصویر گم ہو تو اسے SVG کے اندر data URI کے طور پر ایمبیڈ کریں۔ کنورٹر بیرونی فائلیں نہیں لا سکتا، اس لیے تصویر SVG کے اندر سفر کرنی چاہیے۔</p>\n<h2 id=\"mobile-tips\">فون اور ٹیبلٹ کے لیے نکات</h2>\n<p>فون پر اپ لوڈ والے حصے پر ٹیپ کریں اور اپنے آلے سے SVG فائلیں چنیں۔ تبدیلی فون پر چلتی ہے، اور PNG آپ کے آلے پر ڈاؤن لوڈ ہوتی ہیں۔</p>\n<p>فون کے بیچ چھوٹے رکھیں، کیونکہ پیچیدہ SVG موبائل پروسیسر پر ریسٹرائز ہونے میں وقت لیتی ہیں۔ ایک وقت میں دس فائلیں آرام دہ ہیں۔</p>\n<p>SVG سے PNG میں تبدیل شدہ تصویر فون کے Downloads فولڈر میں جاتی ہے۔ آئی فون والے Files ایپ میں دیکھیں، اینڈرائیڈ والے اپنے فائل مینیجر سے ڈھونڈیں۔</p>\n<h2 id=\"logo-for-business-card\">بزنس کارڈ کے لیے لوگو بدلنا</h2>\n<p>بزنس کارڈ لوگو کو چھوٹے سائز پر تیز پرنٹ ہونا ہوتا ہے، اس لیے SVG کو 4x پر ریسٹرائز کریں۔ کافی پکسل والا چھوٹا لوگو کارڈ پر صاف رہتا ہے۔</p>\n<p>بدلنے کے بعد رنگ جانچیں، کیونکہ پرنٹ رنگ اسکرین رنگوں سے مختلف ہوتے ہیں۔ فوری آزمائشی پرنٹ کاغذ پر برانڈ رنگ درست لگنا یقینی کرتا ہے۔</p>\n<p>PNG پرنٹ شاپ کو SVG بیک اپ کے ساتھ بھیجیں۔ شاپ خود SVG ریسٹرائز کر سکتی ہے اگر PNG میں مسئلہ ہو، اس لیے دونوں دینے سے ہر صورت پوری ہوتی ہے۔</p>\n<h2 id=\"icons-for-website\">ویب سائٹ کے لیے آئیکن بدلنا</h2>\n<p>ویب سائٹ آئیکن SVG فائلوں کے طور پر شروع ہوتے ہیں، اور پرانے براؤزر کے لیے PNG بن جاتے ہیں۔ دکھائی دینے والے سائز کے 2x یا 3x پر ریسٹرائز کریں، تاکہ آئیکن ریٹنا اسکرین پر تیز لگیں۔</p>\n<p>پورے آئیکن سیٹ کے لیے ایک ہی اسکیل استعمال کریں۔ مستقل مزاجی اہم ہے جب آئیکن ساتھ دکھائی دیں، کیونکہ ملے جلے سائز غیر ہموار لگتے ہیں۔</p>\n<p>شائع کرنے سے پہلے آئیکن اصل ویب سائٹ پر آزمائیں۔ ڈیزائن ٹول میں بہترین لگنے والا آئیکن سائٹ کے پس منظر رنگ کے خلاف مختلف لگ سکتا ہے۔</p>\n<h2 id=\"svg-for-tshirt-print\">ٹی شرٹ پرنٹ کے لیے SVG بدلنا</h2>\n<p>ٹی شرٹ پرنٹ کو اونچی ریزولوشن تصویر چاہیے ہوتی ہے، اور SVG مثالی ماخذ ہے۔ صاف پرنٹ کے لیے ٹول کی اجازت والے سب سے بڑے اسکیل پر ریسٹرائز کریں، 8000 پکسل حد تک۔</p>\n<p>بدلنے کے بعد ڈیزائن جانچیں، کیونکہ ٹی شرٹ پرنٹ ہر خامی دکھاتا ہے۔ اسکرین پر ٹھیک لگنے والا لوگو کپڑے پر بڑا پرنٹ ہونے پر کھردرے کنارے ظاہر کر سکتا ہے۔</p>\n<p>PNG پرنٹ شاپ کو SVG بیک اپ کے ساتھ بھیجیں۔ شاپ کا سافٹ ویئر ایک فارمیٹ کو دوسرے پر ترجیح دے سکتا ہے، اور دونوں دینے سے ہر صورت پوری ہوتی ہے۔</p>\n<h2 id=\"svg-for-presentation\">پریزنٹیشن کے لیے SVG بدلنا</h2>\n<p>پریزنٹیشن سلائیڈوں کو تیز لوگو چاہییں ہوتے ہیں، اور SVG مثالی ماخذ ہے۔ SVG سائز کے 4x پر ریسٹرائز کریں، تاکہ لوگو بڑی اسکرین پر پروجیکٹ ہونے پر صاف رہے۔</p>\n<p>بدلنے کے بعد لوگو اصل سلائیڈ پس منظر پر جانچیں۔ سفید پر بہترین لگنے والا لوگو رنگ والی سلائیڈ پر ہلکا کنارہ دکھا سکتا ہے اگر کوالٹی کم تھی۔</p>\n<p>کئی سلائیڈوں والے ڈیک کے لیے تمام لوگو ایک ساتھ بدلیں۔ بیچ تبدیلی میں منٹ لگتے ہیں، اور PNG سلائیڈوں میں ڈالنے کے لیے تیار ہوتی ہیں۔</p>\n<h2 id=\"svg-for-favicon\">فیویکن کے لیے SVG بدلنا</h2>\n<p>فیویکن براؤزر ٹیب میں چھوٹا آئیکن ہوتا ہے، اور یہ عام طور پر SVG لوگو کے طور پر شروع ہوتا ہے۔ معیاری فیویکن سائز کے لیے اسے 16، 32 اور 48 پکسل پر ریسٹرائز کریں۔</p>\n<p>فیویکن سادہ ڈیزائن کریں، کیونکہ چھوٹے سائز تفصیل چھپا دیتے ہیں۔ 16 پکسل پر پیچیدہ لوگو دھندلا بن جاتا ہے، جبکہ سادہ شکل پہچانی جا سکتی ہے۔</p>\n<p>شامل کرنے کے بعد فیویکن کئی براؤزر میں آزمائیں۔ فوری جانچ یقینی کرتی ہے کہ وہ ہر ٹیب میں درست دکھائی دیتا ہے، اس لیے سائٹ ہر جگہ صاف لگتی ہے۔</p>\n<h2 id=\"svg-for-website-banner\">ویب سائٹ بینر کے لیے SVG بدلنا</h2>\n<p>ویب سائٹ بینر چوڑی تصویر ہوتی ہے، اور جب بینر تصویر کی بجائے گرافک ہو تو SVG مثالی ماخذ ہے۔ تیز نتیجے کے لیے بینر کی دکھائی دینے والی چوڑائی پر ریسٹرائز کریں۔</p>\n<p>بدلنے سے پہلے بینر ابعاد جانچیں۔ 1200 پکسل چوڑا دکھایا جانے والا بینر کم از کم اتنی چوڑائی والی PNG مانگتا ہے، ورنہ وہ نرم لگے گا۔</p>\n<p>متن والے بینر کے لیے دکھائی دینے والے سائز کے 2x پر ریسٹرائز کریں۔ متن ریٹنا اسکرین پر تیز رہتا ہے، اور فائل تیزی سے کھلنے کے لیے کافی چھوٹی رہتی ہے۔</p>\n<p>پورا طریقہ یہی ہے: تیار کریں، اپ لوڈ کریں، اسکیل چنیں، ڈاؤن لوڈ کریں۔ پس منظر کے لیے <a href=\"/ur/blog/svg-ko-png-rehnumai/\">SVG to PNG: Complete Guide</a> پڑھیں، اور ویکٹر بمقابلہ ریسٹر سوال کے لیے <a href=\"/ur/blog/svg-vs-png-vector-raster/\">SVG vs PNG: Vector vs Raster Explained</a> دیکھیں۔ اگر آپ کی SVG ملے جلے بیچ کا حصہ ہیں تو <a href=\"/ur/tasveer-convert-karein/\">Image Converter</a> انہیں بھی سنبھالتا ہے۔</p>\n";

